package com.personal.assistant.module.backup.service;import com.personal.assistant.common.exception.BusinessException;import com.personal.assistant.module.backup.entity.BackupRecord;import com.personal.assistant.module.backup.mapper.BackupRecordMapper;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;import org.springframework.test.util.ReflectionTestUtils;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class)class BackupServiceTest{@Mock BackupRecordMapper records;BackupService service;@BeforeEach void setUp(){service=new BackupService(records);ReflectionTestUtils.setField(service,"script","Z:/missing/backup.sh");ReflectionTestUtils.setField(service,"directory","build/backup");ReflectionTestUtils.setField(service,"retentionDays",14);}@Test void missingScriptCreatesFailedRecord(){assertThrows(BusinessException.class,service::runFullBackup);ArgumentCaptor<BackupRecord> c=ArgumentCaptor.forClass(BackupRecord.class);verify(records).insert(c.capture());verify(records).updateById(c.getValue());assertEquals("FAILED",c.getValue().getStatus());assertTrue(c.getValue().getMessage().contains("不存在"));}}